var calc_output = [];
// no UOMSYSTEM needed because the system auto-converts toggleables to SI units
var height = parseFloat(height) / 100; // height is in cm, we need it in m, so divide by 100, bc it's already converted from inches
var weight = parseFloat(weight); // weight is in kg, and system auto-converts lbs to kgs
var v = weight / Math.pow(height, 2);
var u = ((weight * height * 100) / 3600);
u = Math.pow(u, 0.5);
var target = parseFloat(target);
var new_weight = target*Math.pow(height, 2);
var units;
var message;

if (UOMSYSTEM == false){
units = 'kg';
new_weight = new_weight;}
if (UOMSYSTEM == true){
new_weight = new_weight/0.453592;
units = 'lbs';}

if (v.toFixed(1) < 18.5){
  message = 'Underweight';
}
else if (v.toFixed(1) >= 18.5 && v < 25){
  message = 'Normal weight';
}
else if (v.toFixed(1) >= 25 && v < 30){
  message = 'Overweight';
}
else if (v.toFixed(1) >= 30 && v < 35){
  message = 'Class 1 obesity';
}
else if (v.toFixed(1) >= 35 && v < 40){
  message = 'Class 2 obesity';
}
else if (v.toFixed(1) >= 40){
  message = 'Class 3 obesity';
}

calc_output.push({
  name: 'mini',
  value: v.toFixed(1),
  value_text: 'kg/m\u00B2',
  message: 'Body Mass Index'
});
calc_output.push({
  name: '29_BMI & BSA_result (BMI)',
  value: v.toFixed(1),
  value_text: 'kg/m\u00B2',
  message: 'Body Mass Index (' + message + ')'
});
calc_output.push({
  name: '29_BMI & BSA_result (BSA)',
  value: u.toFixed(2),
  value_text: 'm\u00B2',
  message: 'Body Surface Area'
});
if (target > 0){
  calc_output.push({
  name: '29_BMI & BSA_result (target)',
  value: new_weight.toFixed(0),
  value_text: units,
  message: 'Target weight for BMI ' + target + ' kg/m²'
});}
